# Notfall-KI Hilfsfunktionen (Windows PowerShell 5.1, 64 Bit)
# Wird vom Ausfuehrer vor jeder Aktion und vor der Bestandsaufnahme geladen.
# Nur ASCII in dieser Datei: Windows PowerShell 5.1 liest Skripte ohne BOM als ANSI.
# Variablen, die der Ausfuehrer vorher setzt:
#   $NkRoot          Wurzel des Werkzeugkastens auf der SSD (ohne Leerzeichen)
#   $NkBackup        eigener, leerer Sicherungsordner fuer diesen Aktionslauf (auf der SSD)
#   $NkParam         Hashtable mit gepruefte Parametern (nur Werte aus der Erkennung)
#   $NkStart         [datetime] Startzeit der Aktion (bleibt ueber Neustarts erhalten)
#   $NkToolBuildDate [datetime] Erstellungsdatum des Werkzeugkastens (Plausibilitaet der Uhr)

function Test-NkAdmin {
    $id = [Security.Principal.WindowsIdentity]::GetCurrent()
    (New-Object Security.Principal.WindowsPrincipal($id)).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

function Write-NkJson {
    param([Parameter(Mandatory = $true)]$InputObject, [Parameter(Mandatory = $true)][string]$Path)
    ConvertTo-Json -InputObject $InputObject -Depth 10 | Set-Content -LiteralPath $Path -Encoding UTF8
}

function Read-NkJson {
    param([Parameter(Mandatory = $true)][string]$Path)
    Get-Content -LiteralPath $Path -Raw -Encoding UTF8 | ConvertFrom-Json
}

function Invoke-NkNative {
    # Startet ein Konsolenprogramm. stderr loest in PS 5.1 sonst bei ErrorActionPreference=Stop eine Ausnahme aus.
    # Ausgaben sind lokalisiert: ausgewertet wird nur der Exit-Code.
    param(
        [Parameter(Mandatory = $true)][string]$FilePath,
        [string[]]$ArgumentList = @(),
        [int[]]$OkExitCodes = @(0)
    )
    $old = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        $out = & $FilePath @ArgumentList 2>&1 | ForEach-Object { "$_" }
        $code = $LASTEXITCODE
    } finally {
        $ErrorActionPreference = $old
    }
    [pscustomobject]@{ ExitCode = $code; Ok = ($OkExitCodes -contains $code); Output = @($out) }
}

function Save-NkRegKey {
    # Exportiert einen Registrierungsschluessel. Fehlt er, entsteht eine Markierungsdatei <Datei>.absent.
    param([Parameter(Mandatory = $true)][string]$Key, [Parameter(Mandatory = $true)][string]$File)
    if (-not (Test-Path -LiteralPath ('Registry::' + $Key))) {
        Set-Content -LiteralPath ($File + '.absent') -Value $Key -Encoding UTF8
        return $false
    }
    $r = Invoke-NkNative -FilePath 'reg.exe' -ArgumentList @('export', $Key, $File, '/y')
    if (-not $r.Ok) { throw "reg export fehlgeschlagen: $Key" }
    return $true
}

function Restore-NkRegKey {
    param([Parameter(Mandatory = $true)][string]$Key, [Parameter(Mandatory = $true)][string]$File)
    if (Test-Path -LiteralPath ($File + '.absent')) {
        # Schluessel gab es vorher nicht: den von der Aktion angelegten Schluessel entfernen.
        Remove-Item -LiteralPath ('Registry::' + $Key) -Recurse -Force -ErrorAction SilentlyContinue
        return
    }
    $r = Invoke-NkNative -FilePath 'reg.exe' -ArgumentList @('import', $File)
    if (-not $r.Ok) { throw "reg import fehlgeschlagen: $File" }
}

function Get-NkDefaultGateway {
    Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction SilentlyContinue |
        Sort-Object { $_.RouteMetric + $_.InterfaceMetric } |
        Select-Object -First 1 -ExpandProperty NextHop
}

function Test-NkPing {
    # Liefert einen sprachunabhaengigen Code. 11050 = IP_GENERAL_FAILURE ("Allgemeiner Fehler").
    param([Parameter(Mandatory = $true)][string]$Target, [int]$TimeoutMs = 1000)
    $code = $null
    try {
        $reply = (New-Object System.Net.NetworkInformation.Ping).Send($Target, $TimeoutMs)
        $code = [int]$reply.Status
    } catch {
        $e = $_.Exception
        while ($e -and -not ($e -is [System.ComponentModel.Win32Exception])) { $e = $e.InnerException }
        if ($e) { $code = $e.NativeErrorCode } else { $code = -1 }
    }
    $name = switch ($code) {
        0 { 'SUCCESS' }
        11002 { 'NET_UNREACHABLE' }
        11003 { 'HOST_UNREACHABLE' }
        11010 { 'TIMED_OUT' }
        11050 { 'GENERAL_FAILURE' }
        1231 { 'NET_UNREACHABLE' }
        1232 { 'HOST_UNREACHABLE' }
        default { 'OTHER' }
    }
    [pscustomobject]@{ Target = $Target; Code = $code; Result = $name }
}

function Test-NkTcp {
    # 10013 (WSAEACCES) beim Verbindungsaufbau deutet auf einen lokalen Filter (WFP) hin.
    param([Parameter(Mandatory = $true)][string]$Target, [int]$Port = 443, [int]$TimeoutMs = 2000)
    $client = New-Object System.Net.Sockets.TcpClient
    $res = 'ERROR'
    try {
        $iar = $client.BeginConnect($Target, $Port, $null, $null)
        if ($iar.AsyncWaitHandle.WaitOne($TimeoutMs, $false)) {
            try {
                $client.EndConnect($iar)
                $res = 'CONNECTED'
            } catch {
                $e = $_.Exception
                while ($e -and -not ($e -is [System.Net.Sockets.SocketException])) { $e = $e.InnerException }
                $code = $(if ($e) { $e.NativeErrorCode } else { -1 })
                $res = switch ($code) {
                    10013 { 'BLOCKED_LOCAL' }
                    10051 { 'NET_UNREACHABLE' }
                    10060 { 'TIMEOUT' }
                    10061 { 'REFUSED' }
                    10065 { 'HOST_UNREACHABLE' }
                    default { 'ERROR_' + $code }
                }
            }
        } else {
            $res = 'TIMEOUT'
        }
    } catch {
        $res = 'ERROR'
    } finally {
        $client.Close()
    }
    [pscustomobject]@{ Target = $Target; Port = $Port; Result = $res }
}

function Test-NkDns {
    # Mit -Server geht die Anfrage direkt an den Server (nicht aus dem Zwischenspeicher).
    # NXDOMAIN heisst: der Server antwortet, DNS funktioniert.
    param([string]$Name = 'www.msftconnecttest.com', [string]$Server)
    $q = @{ Name = $Name; Type = 'A'; DnsOnly = $true; QuickTimeout = $true; ErrorAction = 'Stop' }
    if ($Server) { $q['Server'] = $Server }
    try {
        $answers = @(Resolve-DnsName @q | Where-Object { $_.Type -eq 'A' })
        [pscustomobject]@{ Name = $Name; Server = $Server; Result = 'RESOLVED'; Code = 0; Count = $answers.Count }
    } catch {
        $code = $null
        $e = $_.Exception
        while ($e) {
            if ($e -is [System.ComponentModel.Win32Exception]) { $code = $e.NativeErrorCode; break }
            $e = $e.InnerException
        }
        $res = 'FAILED'
        if ($code -eq 9003) { $res = 'NXDOMAIN' } elseif ($code -eq 1460) { $res = 'TIMEOUT' }
        [pscustomobject]@{ Name = $Name; Server = $Server; Result = $res; Code = $code; Count = 0 }
    }
}

function Get-NkWinHttpProxyFlags {
    # WinHttpSettings: Byte 8 enthaelt die Flags, Bit 2 = Proxy gesetzt.
    $v = (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Internet Settings\Connections' -Name WinHttpSettings -ErrorAction SilentlyContinue).WinHttpSettings
    if (-not $v -or $v.Length -lt 12) { return 'DIRECT' }
    if ($v[8] -band 2) { 'PROXY' } else { 'DIRECT' }
}

