}

$gw = Get-NkDefaultGateway
$up = @(Get-NetAdapter -ErrorAction SilentlyContinue | Where-Object { "$($_.Status)" -eq 'Up' })
$ownIp = @(Get-NetIPAddress -AddressFamily IPv4 -ErrorAction SilentlyContinue | Where-Object { $_.IPAddress -notlike '127.*' -and $_.IPAddress -notlike '169.254.*' -and "$($_.AddressState)" -eq 'Preferred' }) | Select-Object -First 1
$lo = (Test-NkPing -Target '127.0.0.1').Result
$own = $(if ($ownIp) { (Test-NkPing -Target $ownIp.IPAddress).Result } else { 'NO_ADDRESS' })
$gwr = $(if ($gw) { (Test-NkPing -Target $gw).Result } else { 'NO_GATEWAY' })
$arp = $(if ($gw) { "$((Get-NetNeighbor -IPAddress $gw -ErrorAction SilentlyContinue | Select-Object -First 1).State)" } else { '' })
$tcp = (Test-NkTcp -Target '1.1.1.1' -Port 443).Result
$outBlock = @(Get-NetFirewallProfile -PolicyStore ActiveStore -ErrorAction SilentlyContinue | Where-Object { "$($_.DefaultOutboundAction)" -eq 'Block' }).Count
$next = 'UNCLEAR'
if ($lo -ne 'SUCCESS') { $next = 'STACK_BROKEN' }
elseif (-not $up.Count -or $own -eq 'NO_ADDRESS' -or $gwr -eq 'NO_GATEWAY') { $next = 'NO_VALID_INTERFACE' }
elseif ($gwr -eq 'GENERAL_FAILURE' -or $tcp -eq 'BLOCKED_LOCAL') { $next = 'LOCAL_FILTER' }
elseif (@('TIMED_OUT', 'HOST_UNREACHABLE') -contains $gwr) { $next = 'LINK_OR_ROUTER' }
elseif ($gwr -eq 'SUCCESS') { $next = 'GATEWAY_OK' }
[pscustomobject]@{ Loopback = $lo; OwnIp = $own; Gateway = $gw; PingGateway = $gwr; ArpGateway = $arp; Tcp443 = $tcp; OutboundBlockProfiles = $outBlock; Next = $next }

