$sa = 'Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved'
$src = @(
    @{ Scope = 'HKCU'; Kind = 'Run'; Key = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run' },
    @{ Scope = 'HKLM'; Kind = 'Run'; Key = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run' },
    @{ Scope = 'HKLM'; Kind = 'Run32'; Key = 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run' }
)
$rows = foreach ($s in $src) {
    $item = Get-Item -Path $s.Key -ErrorAction SilentlyContinue
    if (-not $item) { continue }
    foreach ($name in $item.GetValueNames()) {
        if (-not $name) { continue }
        $cmd = [string]$item.GetValue($name)
        $ap = (Get-ItemProperty -Path ("$($s.Scope):\$sa\$($s.Kind)") -Name $name -ErrorAction SilentlyContinue).$name
        [pscustomobject]@{ Scope = $s.Scope; Kind = $s.Kind; Name = $name; Command = $cmd; Enabled = -not ($ap -and ($ap[0] -band 1)); Protected = (Test-NkProtectedStartup -Name $name -Command $cmd) }
    }
}
$folders = @(
    @{ Scope = 'HKCU'; Dir = [Environment]::GetFolderPath('Startup') },
    @{ Scope = 'HKLM'; Dir = [Environment]::GetFolderPath('CommonStartup') }
)
$rows2 = foreach ($fo in $folders) {
    foreach ($f in @(Get-ChildItem -LiteralPath $fo.Dir -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne 'desktop.ini' })) {
        $ap = (Get-ItemProperty -Path ("$($fo.Scope):\$sa\StartupFolder") -Name $f.Name -ErrorAction SilentlyContinue).($f.Name)
        [pscustomobject]@{ Scope = $fo.Scope; Kind = 'StartupFolder'; Name = $f.Name; Command = $f.FullName; Enabled = -not ($ap -and ($ap[0] -band 1)); Protected = (Test-NkProtectedStartup -Name $f.Name -Command $f.FullName) }
    }
}
@($rows) + @($rows2)

